function parseLedger(markdown) {
  // Brief 01 (binding): only the section whose heading line is exactly
  // `## Transaction Ledger` is authoritative. Do not match "working copy".
  // Also: locate boundaries with regex anchored to whole heading lines.
  const headingRe = /^## Transaction Ledger\s*$/m;
  const m = markdown.match(headingRe);
  if (!m || m.index == null) return [];

  // Slice just the authoritative section (until next H2 heading or EOF)
  const afterHeadingIdx = m.index + m[0].length;
  const rest = markdown.slice(afterHeadingIdx);
  const nextH2 = rest.search(/^##\s+/m);
  const section = nextH2 >= 0 ? rest.slice(0, nextH2) : rest;

  // Parse TXN blocks. If duplicates exist, last non-provisional wins.
  const byId = new Map();
  const blocks = section.split(/^### /m).slice(1);
  for (const block of blocks) {
    const lines = block.split("\n");
    const transactionId = (lines[0] || "").trim();
    if (!transactionId.startsWith("TXN-")) continue;

    // Skip any ledger block with `provisional: true` (case-insensitive)
    const provisional = lines.some((l) => /^\s*provisional\s*:\s*true\s*$/i.test(l));
    if (provisional) continue;

    const row = { transaction_id: transactionId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.toLowerCase().startsWith("amount:")) {
        row.amount = Number(trimmed.split(":")[1].trim());
      } else if (trimmed.toLowerCase().startsWith("owner:")) {
        row.owner = trimmed.split(":")[1].trim();
      } else if (trimmed.toLowerCase().startsWith("status:")) {
        row.status = trimmed.split(":")[1].trim();
      } else if (trimmed.toLowerCase().startsWith("date:")) {
        row.date = trimmed.split(":")[1].trim();
      }
    }

    byId.set(transactionId, row);
  }

  return [...byId.values()];
}

module.exports = { parseLedger };
EOF
