function parseEmails(markdown) {
  // Use authoritative structured section boundaries (decoy headings exist).
  const startMatch = markdown.match(/^## Email Excerpts\s*$/m);
  if (!startMatch || startMatch.index == null) return [];

  const afterStart = startMatch.index + startMatch[0].length;
  const rest = markdown.slice(afterStart);
  const endIdxInRest = rest.search(/^## Policy Exceptions\s*$/m);
  const slice = endIdxInRest >= 0 ? rest.slice(0, endIdxInRest) : rest;

  const emails = [];
  const blocks = slice.split(/\n\n+/);
  for (const block of blocks) {
    const fromMatch = block.match(/^From:\s*(.+)$/im);
    const subjectMatch = block.match(/^Subject:\s*Re:\s*(TXN-[0-9a-f-]+)/im);
    const statusMatch = block.match(/^status:\s*(\w+)/im);
    const dateMatch = block.match(/^Date:\s*(.+)$/im);

    if (!fromMatch || !subjectMatch || !statusMatch) continue;

    emails.push({
      from_addr: fromMatch[1].trim(),
      transaction_id: subjectMatch[1],
      status: statusMatch[1].trim().toLowerCase(),
      date: dateMatch ? dateMatch[1].trim() : null,
    });
  }

  return emails;
}

module.exports = { parseEmails };
